import { after } from 'next/server';
import { headers } from 'next/headers';
import { logPageView } from '../utils/analytics';

export default async function WelcomePage() {
  // Read request data BEFORE the after callback
  // This must be done during the component's rendering lifecycle
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') || 'unknown';

  // Schedule analytics logging to run AFTER the response is sent
  // This does NOT block the response
  after(() => {
    logPageView({
      page: '/welcome',
      userAgent,
      timestamp: new Date().toISOString(),
    });
  });

  return (
    <div>
      <h1>Welcome!</h1>
      <p>Thank you for visiting our site.</p>
      <p>This page view is being logged asynchronously without blocking your experience.</p>
    </div>
  );
}

